dtsPropsFor.Figure:
/** The hero statistic. `value` and `label` are both required — a spec missing either renders nothing at all. */
  spec: { value: string | number; unit?: string; label: string; source?: string };
  /** Server-side grounding verdict. ONLY "exact" | "rounded" | "derived" render the quiet "✓ verified" mark; every other value (and undefined) renders NO mark and NO warning. Positive-only by design — never add an "unverified" state. */
  grounding?: "exact" | "rounded" | "derived" | "ungrounded" | "no_figure" | "malformed" | "unchecked";

dtsPropsFor.Chart:
/** Data and axes. Renders null unless `data` is a non-empty array and `x` is set. */
  spec: { x: string; y: string | string[]; data: Array<Record<string, string | number>>; type?: "line" | "bar"; title?: string; xLabel?: string; yLabel?: string };
  /** True only inside ChartModal — hides this chart's own maximize control. */
  inModal?: boolean;
  /** Initial chart type. Defaults from `spec.type` (bar if it says bar, else line). */
  initialType?: "line" | "bar";
  /** Start with the least-squares trend line drawn. It only appears on a LINE chart whose x-axis is time-like (year/date/month/quarter/day) with >= 3 points — a fitted slope across categories is meaningless. */
  initialTrend?: boolean;
  /** Start with per-point data labels shown. */
  initialLabels?: boolean;

dtsPropsFor.ChartModal:
/** Same spec the opener Chart was rendering. */
  spec: { x: string; y: string | string[]; data: Array<Record<string, string | number>>; type?: "line" | "bar"; title?: string; xLabel?: string; yLabel?: string };
  /** Carry the opener's current view so maximizing doesn't reset it. */
  initialType?: "line" | "bar";
  initialTrend?: boolean;
  initialLabels?: boolean;
  /** Called on EVERY dismissal path (Close button, Escape, overlay click). Required — the dialog never closes itself, and focus returns to the opener on unmount. */
  onClose: () => void;

dtsPropsFor.Markdown:
/** The Markdown source, as a plain string. Rendered with GFM. Raw HTML is deliberately NOT enabled (no rehype-raw, default URL sanitizer intact) because this renders model output — keep it that way. */
  children: string;
  /** Message id used for the server-side full-result CSV re-run. Honoured only when the answer contains EXACTLY ONE table; otherwise the button falls back to exporting the transcribed rows. */
  messageId?: number | string | null;
  /** True when the stored result rows were cut at the server row cap. Adds the "First N rows" caption and the warn-toned sort note. */
  resultsTruncated?: boolean;

dtsPropsFor.MarkdownTextarea:
/** Controlled value — always the RAW Markdown string. The highlighting is a colored <pre> mirror behind a transparent <textarea>, never a rich-text model. */
  value: string;
  onChange: (e: React.ChangeEvent<HTMLTextAreaElement>) => void;
  onKeyDown?: (e: React.KeyboardEvent<HTMLTextAreaElement>) => void;
  placeholder?: string;
  id?: string;
  className?: string;
  autoFocus?: boolean;
  /** Hard character cap. The composer keeps this in sync with the server's MAX_QUESTION_LEN (4000). */
  maxLength?: number;
  "aria-label"?: string;

dtsPropsFor.SqlBlock:
/** The SQL text. Every SQL surface in the product renders through this component. */
  code: string;
  className?: string;
  /** Pretty-print before highlighting. Pass false for author-written ```sql fences (highlight only, leave their formatting alone). */
  format?: boolean;

dtsPropsFor.Suggestions:
/** Follow-up questions. Non-string and empty entries are dropped; an empty list renders nothing. */
  items: string[];
  /** Called with the clicked question — the caller submits it as an ordinary follow-up turn. */
  onAsk: (question: string) => void;
  disabled?: boolean;

dtsPropsFor.Clarify:
/** The blocking clarification. `options` are SHORT answer phrases ("bachelor's only"), never restated questions. */
  spec: { question: string; options: string[] };
  onAsk: (answer: string) => void;
  disabled?: boolean;
  /** Show the model's actual question as the label instead of the default "Did you mean". */
  showQuestion?: boolean;

dtsPropsFor.BulkBar:
/** Row-type nouns, e.g. { one: "user", many: "users" }. Drives every count string. */
  nouns: { one: string; many: string };
  /** "page" = the current page's selection; "all" = every matching row (and then `selectedIds` upstream holds EXCLUSIONS, not selections). */
  mode: "page" | "all";
  /** Selected row count. The whole toolbar renders nothing at 0 — it is contextual, never a persistent strip of disabled buttons. */
  count: number;
  totalEligible: number;
  pageSelectedCount: number;
  pageEligibleCount: number;
  /** Invoked by the "select all N matching" banner, which appears once a full page is selected and more rows match. */
  onSelectAllMatching: () => void;
  onClear: () => void;
  /** Action buttons, in order. Labels use STABLE verbs (no counts — the count belongs in the confirm dialog). Any `variant: "danger"` action is split off behind a divider in the danger colour. */
  actions: Array<{ key: string; label: string; icon: React.ComponentType<{ size?: number }>; onClick: () => void; variant?: "danger"; disabled?: boolean; title?: string }>;
  /** Called before clear/escalate so focus never lands on a control that is about to disappear. */
  onFocusFallback?: () => void;

dtsPropsFor.CopyMenu:
onCopyMarkdown: () => void;
  onCopyHtml: () => void;
  /** Flips the trigger to a "Copied!" check. The caller owns the reset timer. */
  copied?: boolean;

dtsPropsFor.HelpPopover:
/** Accessible name for the trigger button. */
  label: string;
  /** Popover body. */
  children: React.ReactNode;
  /** Trigger glyph. Defaults to IconHelp; pass any icon from this system. */
  icon?: React.ComponentType<{ size?: number }>;
  className?: string;

dtsPropsFor.UserMenu:
/** Signed-in address. The avatar's initials are derived from it (first.last -> "TW"; a +tag is stripped). */
  email: string;
  /** Adds the Admin item and lets the attention badge render. */
  isAdmin?: boolean;
  /** Count of things awaiting an admin. Rendered through the capped formatBadge: "" at 0, the number to 99, then "99+". Accent-toned — a queue is work waiting, never a red failure. */
  attentionTotal?: number;
  theme: "light" | "dark";
  /** The ONE menu item that deliberately keeps the menu open on activation. */
  onToggleTheme: () => void;
  onSignOut: () => void;
  onAbout: () => void;

dtsPropsFor.AboutModal:
/** Called on every dismissal path. Required. */
  onClose: () => void;
  /** Gates the admin-guide link. */
  isAdmin?: boolean;
  /** Running and latest version; shows the update note when `update_available` is true. */
  version?: { current: string; latest?: string | null; update_available?: boolean } | null;

dtsPropsFor.DataTable:
/** All rows, unpaginated — this component owns search, sort and paging client-side. */
  rows: Array<Record<string, unknown>>;
  /** `render` defaults to row[key]. */
  columns: Array<{ key: string; label: string; sortable?: boolean; render?: (row: any) => React.ReactNode; cellTitle?: (row: any) => string; colClass?: string; thClass?: string; cellClass?: string }>;
  /** Returns a stable unique key for a row — the React key AND the focus target. This is a FUNCTION, e.g. `(r) => r.email`, not the name of a field. */
  rowKey: (row: any) => string | number;
  /** The datatable.js config. `comparators` and `tiebreak` are REQUIRED — sortRows does Object.keys(comparators), so omitting them throws "Cannot convert undefined or null to object" and the table renders blank. Define the DEFAULT-SORT column first in `comparators` (an unknown sortKey falls back to the first). `tiebreak` must be unique per row: without a total order, a refetch can reshuffle which rows land on the current page. */
  config: { fields: string[]; comparators: Record<string, (a: any, b: any) => number>; tiebreak: (row: any) => string | number; nouns: { one: string; many: string } };
  searchPlaceholder?: string;
  searchLabel?: string;
  searchId?: string;
  /** Shown when there are no rows at all — keep it DISTINCT from a load failure, which must never look like an empty result. */
  emptyNoData?: string;
  /** Shown when the search filtered everything out. */
  emptyNoMatch?: string;
  /** Defaults to the first sortable column, ascending. */
  initialSort?: { key: string; dir?: "asc" | "desc" };
  pageSizes?: number[];
  defaultPageSize?: number;
  sizeLabel?: string;
  ariaLabel?: string;
  renderActions?: (row: any) => React.ReactNode;
  sortLabels?: Record<string, string>;
  tableClass?: string;
  onSearchChange?: (q: string) => void;
  /** Opt-in bulk selection. When falsy NONE of the selection UI renders and the table behaves exactly as it did before selection existed. */
  selectable?: boolean;
  /** Selection-id accessor. Defaults to `rowKey`. */
  selectionId?: (row: any) => string | number;
  /** "all" INVERTS the meaning of `selectedIds`: it then holds the EXCLUDED ids, not the selected ones. */
  selectionMode?: "page" | "all";
  selectedIds?: Set<string | number>;
  /** Rows this returns false for cannot be selected (e.g. your own account). */
  rowSelectable?: (row: any) => boolean;
  rowSelectLabel?: (row: any) => string;
  onToggleRow?: (id: string | number) => void;
  onTogglePage?: () => void;
  /** Renders the contextual selection toolbar (normally BulkBar). Called only while at least one row is selected. */
  renderSelectionBar?: (ctx: any) => React.ReactNode;

